export const FLIGHT_MAP_DIMENSIONS = {
  width: 1000,
  height: 560,
  paddingX: 36,
  paddingY: 34,
  minLatitude: -60,
  maxLatitude: 80,
};

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function roundCoordinate(value) {
  return Math.round(value * 100) / 100;
}

function getInnerWidth(dimensions) {
  return dimensions.width - dimensions.paddingX * 2;
}

function getInnerHeight(dimensions) {
  return dimensions.height - dimensions.paddingY * 2;
}

export function normalizeLongitude(longitude) {
  if (!Number.isFinite(longitude)) {
    return 0;
  }

  const normalized = ((((longitude + 180) % 360) + 360) % 360) - 180;

  if (normalized === -180 && longitude > 0) {
    return 180;
  }

  return normalized;
}

export function buildRouteGroupId(fromAirportCode = "", toAirportCode = "") {
  return [fromAirportCode, toAirportCode].sort().join("-");
}

export function projectMapPoint(
  point = {},
  dimensions = FLIGHT_MAP_DIMENSIONS,
) {
  if (!Number.isFinite(point.lat) || !Number.isFinite(point.lon)) {
    return null;
  }

  const latitude = clamp(
    point.lat,
    dimensions.minLatitude,
    dimensions.maxLatitude,
  );
  const x =
    dimensions.paddingX + ((point.lon + 180) / 360) * getInnerWidth(dimensions);
  const y =
    dimensions.paddingY +
    ((dimensions.maxLatitude - latitude) /
      (dimensions.maxLatitude - dimensions.minLatitude)) *
      getInnerHeight(dimensions);

  return {
    x: roundCoordinate(x),
    y: roundCoordinate(y),
  };
}

function toRadians(value) {
  return (value * Math.PI) / 180;
}

function toDegrees(value) {
  return (value * 180) / Math.PI;
}

function toCartesian(point) {
  const latitude = toRadians(point.lat);
  const longitude = toRadians(point.lon);
  const latitudeCosine = Math.cos(latitude);

  return {
    x: latitudeCosine * Math.cos(longitude),
    y: latitudeCosine * Math.sin(longitude),
    z: Math.sin(latitude),
  };
}

function fromCartesian(point) {
  const hypotenuse = Math.hypot(point.x, point.y);

  return {
    lat: toDegrees(Math.atan2(point.z, hypotenuse)),
    lon: toDegrees(Math.atan2(point.y, point.x)),
  };
}

function normalizeVector(point) {
  const magnitude = Math.hypot(point.x, point.y, point.z) || 1;

  return {
    x: point.x / magnitude,
    y: point.y / magnitude,
    z: point.z / magnitude,
  };
}

function unwrapLongitudeSequence(points) {
  if (points.length === 0) {
    return [];
  }

  return points.reduce((sequence, point, index) => {
    const normalizedLongitude = normalizeLongitude(point.lon);

    if (index === 0) {
      sequence.push({
        lat: point.lat,
        lon: normalizedLongitude,
      });

      return sequence;
    }

    const previous = sequence[sequence.length - 1];
    let nextLongitude = normalizedLongitude;

    while (nextLongitude - previous.lon > 180) {
      nextLongitude -= 360;
    }

    while (nextLongitude - previous.lon < -180) {
      nextLongitude += 360;
    }

    sequence.push({
      lat: point.lat,
      lon: nextLongitude,
    });

    return sequence;
  }, []);
}

function shiftLongitudeSequence(points, offset) {
  return points.map((point) => ({
    lat: point.lat,
    lon: point.lon + offset,
  }));
}

function buildProjectedPath(points, dimensions) {
  return points
    .map((point) => projectMapPoint(point, dimensions))
    .filter(Boolean)
    .map((point, index) => `${index === 0 ? "M" : "L"} ${point.x} ${point.y}`)
    .join(" ");
}

function buildGreatCirclePoints(fromAirport, toAirport) {
  const start = toCartesian(fromAirport);
  const end = toCartesian(toAirport);
  const dotProduct = clamp(
    start.x * end.x + start.y * end.y + start.z * end.z,
    -1,
    1,
  );
  const centralAngle = Math.acos(dotProduct);

  if (!Number.isFinite(centralAngle) || centralAngle === 0) {
    return [fromAirport, toAirport];
  }

  const segmentCount = clamp(Math.ceil((centralAngle / Math.PI) * 36), 12, 48);
  const sineOfAngle = Math.sin(centralAngle);

  return Array.from({ length: segmentCount + 1 }, (_, index) => {
    const position = index / segmentCount;
    const startScale = Math.sin((1 - position) * centralAngle) / sineOfAngle;
    const endScale = Math.sin(position * centralAngle) / sineOfAngle;
    const point = normalizeVector({
      x: start.x * startScale + end.x * endScale,
      y: start.y * startScale + end.y * endScale,
      z: start.z * startScale + end.z * endScale,
    });

    return fromCartesian(point);
  });
}

export function buildRouteArcPaths(
  fromAirport = {},
  toAirport = {},
  dimensions = FLIGHT_MAP_DIMENSIONS,
) {
  if (
    !Number.isFinite(fromAirport.lat) ||
    !Number.isFinite(fromAirport.lon) ||
    !Number.isFinite(toAirport.lat) ||
    !Number.isFinite(toAirport.lon)
  ) {
    return [];
  }

  const unwrappedPoints = unwrapLongitudeSequence(
    buildGreatCirclePoints(fromAirport, toAirport),
  );

  if (unwrappedPoints.length < 2) {
    return [];
  }

  const longitudes = unwrappedPoints.map((point) => point.lon);
  const minimumLongitude = Math.min(...longitudes);
  const maximumLongitude = Math.max(...longitudes);
  const sequences = [unwrappedPoints];

  if (minimumLongitude < -180) {
    sequences.push(shiftLongitudeSequence(unwrappedPoints, 360));
  }

  if (maximumLongitude > 180) {
    sequences.push(shiftLongitudeSequence(unwrappedPoints, -360));
  }

  return [
    ...new Set(
      sequences
        .map((points) => buildProjectedPath(points, dimensions))
        .filter(Boolean),
    ),
  ];
}

function buildPolygonRingPath(ring = [], dimensions = FLIGHT_MAP_DIMENSIONS) {
  const commands = ring
    .map((coordinate, index) => {
      if (!Array.isArray(coordinate) || coordinate.length < 2) {
        return "";
      }

      const point = projectMapPoint(
        {
          lat: Number(coordinate[1]),
          lon: normalizeLongitude(Number(coordinate[0])),
        },
        dimensions,
      );

      if (!point) {
        return "";
      }

      return `${index === 0 ? "M" : "L"} ${point.x} ${point.y}`;
    })
    .filter(Boolean);

  if (commands.length === 0) {
    return "";
  }

  return `${commands.join(" ")} Z`;
}

function buildPolygonPath(
  coordinates = [],
  dimensions = FLIGHT_MAP_DIMENSIONS,
) {
  return coordinates
    .map((ring) => buildPolygonRingPath(ring, dimensions))
    .filter(Boolean)
    .join(" ");
}

export function buildGeoJsonFeaturePaths(
  featureCollection = {},
  dimensions = FLIGHT_MAP_DIMENSIONS,
) {
  const features = Array.isArray(featureCollection.features)
    ? featureCollection.features
    : [];

  return features
    .flatMap((feature) => {
      const geometry = feature?.geometry;

      if (!geometry?.type || !Array.isArray(geometry.coordinates)) {
        return [];
      }

      if (geometry.type === "Polygon") {
        const path = buildPolygonPath(geometry.coordinates, dimensions);

        return path ? [path] : [];
      }

      if (geometry.type === "MultiPolygon") {
        return geometry.coordinates
          .map((polygon) => buildPolygonPath(polygon, dimensions))
          .filter(Boolean);
      }

      return [];
    })
    .filter(Boolean);
}

function getFlightMiles(row) {
  const miles = Number(row.Miles);

  return Number.isFinite(miles) ? miles : 0;
}

function createAirportNetworkNode(airport) {
  return {
    iata: airport.iata,
    icao: airport.icao,
    name: airport.name,
    flagCode: airport.flagCode,
    lat: airport.lat,
    lon: airport.lon,
    departures: 0,
    arrivals: 0,
    totalFlights: 0,
    totalMiles: 0,
    connectedAirports: new Map(),
  };
}

export function buildFlightMapData(
  rows = [],
  dimensions = FLIGHT_MAP_DIMENSIONS,
) {
  const airportMap = new Map();
  const routeMap = new Map();

  rows.forEach((row) => {
    const { fromAirport, toAirport } = row;

    if (
      !Number.isFinite(fromAirport?.lat) ||
      !Number.isFinite(fromAirport?.lon) ||
      !Number.isFinite(toAirport?.lat) ||
      !Number.isFinite(toAirport?.lon)
    ) {
      return;
    }

    if (!airportMap.has(fromAirport.iata)) {
      airportMap.set(fromAirport.iata, createAirportNetworkNode(fromAirport));
    }

    if (!airportMap.has(toAirport.iata)) {
      airportMap.set(toAirport.iata, createAirportNetworkNode(toAirport));
    }

    const fromNode = airportMap.get(fromAirport.iata);
    const toNode = airportMap.get(toAirport.iata);
    const miles = getFlightMiles(row);

    fromNode.departures += 1;
    fromNode.totalFlights += 1;
    fromNode.totalMiles += miles;
    fromNode.connectedAirports.set(
      toAirport.iata,
      (fromNode.connectedAirports.get(toAirport.iata) || 0) + 1,
    );

    toNode.arrivals += 1;
    toNode.totalFlights += 1;
    toNode.totalMiles += miles;
    toNode.connectedAirports.set(
      fromAirport.iata,
      (toNode.connectedAirports.get(fromAirport.iata) || 0) + 1,
    );

    const routeId = `${fromAirport.iata}-${toAirport.iata}`;

    if (!routeMap.has(routeId)) {
      routeMap.set(routeId, {
        id: routeId,
        fromAirport,
        toAirport,
        flightCount: 0,
        totalMiles: 0,
        rows: [],
      });
    }

    const route = routeMap.get(routeId);
    route.flightCount += 1;
    route.totalMiles += miles;
    route.rows.push(row);
  });

  const airports = [...airportMap.values()]
    .map((airport) => {
      const point = projectMapPoint(airport, dimensions);
      const labelSide =
        point && point.x > dimensions.width - 140 ? "left" : "right";

      return {
        ...airport,
        averageMiles:
          airport.totalFlights > 0
            ? Math.round(airport.totalMiles / airport.totalFlights)
            : 0,
        radius: roundCoordinate(
          clamp(2.2 + Math.sqrt(airport.totalFlights) * 0.45, 2.2, 6),
        ),
        point,
        labelSide,
        connections: [...airport.connectedAirports.entries()]
          .map(([code, count]) => ({ code, count }))
          .sort((left, right) => right.count - left.count),
      };
    })
    .sort((left, right) => {
      if (right.totalFlights !== left.totalFlights) {
        return right.totalFlights - left.totalFlights;
      }

      return left.iata.localeCompare(right.iata);
    });

  const routes = [...routeMap.values()]
    .map((route) => {
      const sortedRows = [...route.rows].sort((left, right) =>
        String(right.Date).localeCompare(String(left.Date)),
      );

      return {
        ...route,
        rows: sortedRows,
        averageMiles:
          route.flightCount > 0
            ? Math.round(route.totalMiles / route.flightCount)
            : 0,
        airlines: [...new Set(sortedRows.map((row) => row.airlineDisplayName))],
        paths: buildRouteArcPaths(
          route.fromAirport,
          route.toAirport,
          dimensions,
        ),
        strokeWidth: roundCoordinate(
          clamp(1.35 + Math.log2(route.flightCount + 1) * 1.7, 1.35, 7),
        ),
      };
    })
    .sort((left, right) => {
      if (right.flightCount !== left.flightCount) {
        return right.flightCount - left.flightCount;
      }

      if (right.totalMiles !== left.totalMiles) {
        return right.totalMiles - left.totalMiles;
      }

      return left.id.localeCompare(right.id);
    });

  const routeGroups = [...routes]
    .reduce((groups, route) => {
      const groupId = buildRouteGroupId(
        route.fromAirport.iata,
        route.toAirport.iata,
      );

      if (!groups.has(groupId)) {
        const [fromCode, toCode] = groupId.split("-");

        groups.set(groupId, {
          id: groupId,
          fromAirport: airportMap.get(fromCode),
          toAirport: airportMap.get(toCode),
          flightCount: 0,
          totalMiles: 0,
          routes: [],
          rows: [],
        });
      }

      const group = groups.get(groupId);
      group.flightCount += route.flightCount;
      group.totalMiles += route.totalMiles;
      group.routes.push(route);
      group.rows.push(...route.rows);

      return groups;
    }, new Map())
    .values();

  const normalizedRouteGroups = [...routeGroups]
    .map((group) => {
      const sortedRows = [...group.rows].sort((left, right) =>
        String(right.Date).localeCompare(String(left.Date)),
      );

      return {
        ...group,
        rows: sortedRows,
        averageMiles:
          group.flightCount > 0
            ? Math.round(group.totalMiles / group.flightCount)
            : 0,
        airlines: [...new Set(sortedRows.map((row) => row.airlineDisplayName))],
        directionSummaries: [...group.routes]
          .map((route) => ({
            id: route.id,
            fromAirport: route.fromAirport,
            toAirport: route.toAirport,
            flightCount: route.flightCount,
            averageMiles: route.averageMiles,
            rows: [...route.rows].sort((left, right) =>
              String(right.Date).localeCompare(String(left.Date)),
            ),
          }))
          .sort((left, right) => {
            if (right.flightCount !== left.flightCount) {
              return right.flightCount - left.flightCount;
            }

            return left.id.localeCompare(right.id);
          }),
        paths: buildRouteArcPaths(
          group.fromAirport,
          group.toAirport,
          dimensions,
        ),
        strokeWidth: roundCoordinate(
          clamp(1.2 + Math.log2(group.flightCount + 1) * 1.45, 1.2, 4.4),
        ),
      };
    })
    .sort((left, right) => {
      if (right.flightCount !== left.flightCount) {
        return right.flightCount - left.flightCount;
      }

      if (right.totalMiles !== left.totalMiles) {
        return right.totalMiles - left.totalMiles;
      }

      return left.id.localeCompare(right.id);
    });

  const totalMiles = rows.reduce((sum, row) => sum + getFlightMiles(row), 0);
  const longestFlight = [...rows]
    .filter((row) => getFlightMiles(row) > 0)
    .sort((left, right) => getFlightMiles(right) - getFlightMiles(left))[0];

  return {
    dimensions,
    airports,
    routes,
    routeGroups: normalizedRouteGroups,
    topRoutes: normalizedRouteGroups.slice(0, 8),
    totalMiles,
    longestFlight,
    busiestAirport: airports[0] || null,
  };
}
