<script setup>
/* eslint-env vue/setup-compiler-macros */
import {
  CTable,
  CTableBody,
  CTableDataCell,
  CTableHead,
  CTableHeaderCell,
  CTableRow,
} from "@coreui/vue";
import { right } from "@popperjs/core";

import cameraIcon from "@/assets/icons/camera.svg";
import { getAirlineLogoSrc, getFlagSrc } from "@/utils/flightLog";

const emit = defineEmits(["sort"]);

const props = defineProps({
  columns: {
    type: Array,
    required: true,
  },
  isIata: {
    type: Boolean,
    required: true,
  },
  rowStart: {
    type: Number,
    required: true,
  },
  rows: {
    type: Array,
    required: true,
  },
  sortBy: {
    type: String,
    required: true,
  },
  sortOrder: {
    type: String,
    required: true,
  },
  sortableColumns: {
    type: Array,
    required: true,
  },
});

function getSortIndicator(column) {
  if (props.sortBy !== column) {
    return "↕";
  }

  return props.sortOrder === "asc" ? "↑" : "↓";
}

function getAirport(row, column) {
  return column === "From" ? row.fromAirport : row.toAirport;
}

function getCellClass(column) {
  return {
    "column-airline": column === "Airline",
    "column-miles": column === "Miles",
    "column-time": ["STD", "ATD", "STA", "ATA"].includes(column),
  };
}
</script>

<template>
  <CTable class="flight-table">
    <CTableHead>
      <CTableRow>
        <CTableHeaderCell scope="col" class="column-index">
          #
        </CTableHeaderCell>
        <CTableHeaderCell v-for="column in columns" :key="column" scope="col">
          <button
            v-if="sortableColumns.includes(column)"
            class="sort-button"
            type="button"
            @click="emit('sort', column)"
          >
            <span>{{ column }}</span>
            <span
              :class="['sort-icon', { active: sortBy === column }]"
              aria-hidden="true"
            >
              {{ getSortIndicator(column) }}
            </span>
          </button>
          <div v-else class="header-label">
            {{ column }}
          </div>
        </CTableHeaderCell>
      </CTableRow>
    </CTableHead>

    <CTableBody>
      <CTableRow
        v-for="(row, rowIndex) in rows"
        :key="row.id"
        class="flight-row"
      >
        <CTableDataCell class="data-cell column-index row-index-cell">
          {{ rowStart + rowIndex + 1 }}
        </CTableDataCell>

        <CTableDataCell
          v-for="column in columns"
          :key="`${row.id}-${column}`"
          :class="['data-cell', getCellClass(column)]"
        >
          <div v-if="column === 'Airline'" class="cell-content airline-cell">
            <img :src="getAirlineLogoSrc(row.airlineLogoCode)" class="logo" />
            <span>{{ row.airlineDisplayName }}</span>
          </div>

          <div
            v-else-if="column === 'From' || column === 'To'"
            v-tooltip="{
              content: getAirport(row, column).name,
              html: true,
              placement: right,
            }"
            class="cell-content airport-cell"
          >
            <img
              :src="getFlagSrc(getAirport(row, column).flagCode)"
              class="country-flag"
            />
            <span>
              {{
                isIata
                  ? getAirport(row, column).iata
                  : getAirport(row, column).icao
              }}
            </span>
          </div>

          <div
            v-else-if="column === 'Registration'"
            class="cell-content registration-cell"
          >
            <div class="cell-content registration-text">
              <img
                :src="getFlagSrc(row.registrationInfo.countryCode)"
                class="country-flag"
              />
              <span>{{ row.registrationInfo.tailNumber }}</span>
              <a
                :href="row.imageUrl"
                v-tooltip="{
                  content: `<div><img src='${row.previewImageUrl}'></div>`,
                  html: true,
                  placement: right,
                }"
              >
                <img :src="cameraIcon" class="camera-icon" />
              </a>
            </div>
          </div>

          <div v-else class="cell-content">
            {{ row[column] }}
          </div>
        </CTableDataCell>
      </CTableRow>
    </CTableBody>
  </CTable>
</template>

